    # Find the full separator row and column.
    sr = next(r for r in range(h) if len(set(grid[r])) == 1)
    sc = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)

    out = [row[:] for row in grid]
    for r in range(h):
        if r == sr:
            continue
        source_r = r if r < sr else r - sr - 1
        for c in range(w):
            if c == sc:
                continue
            source_c = c if c < sc else c - sc - 1
            out[r][c] = grid[source_r][source_c]
    return out
